export function translate(lang, key, vars) {
  const dict = translations[lang] || translations.ar;
  const fallbackDict = translations.ar;
  const lookup = (d) => key.split(".").reduce((acc, k) => (acc && acc[k] !== undefined ? acc[k] : undefined), d);
  let str = lookup(dict);
  if (str === undefined) str = lookup(fallbackDict);
  if (str === undefined) return key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) str = str.replaceAll(`{${k}}`, v);
  }
  return str;
}
